/* SAFE DRY-RUN: replace this sample with read-only Shopify + supplier/location reconciliation before production. Never change inventory here. */
const sample = [
  { sku: 'SAMPLE-TRACKED-ZERO', title: 'Sample tracked product', tracked: true, available: 0, inventoryPolicy: 'DENY', supplierLinked: false, sourceVerified: false },
  { sku: 'SAMPLE-POD-UNTRACKED', title: 'Sample made-to-order product', tracked: false, available: null, inventoryPolicy: 'CONTINUE', supplierLinked: true, sourceVerified: false },
  { sku: 'SAMPLE-IN-STOCK', title: 'Sample stocked product', tracked: true, available: 12, inventoryPolicy: 'DENY', supplierLinked: true, sourceVerified: true }
];
return sample.map(p => {
  const zeroTracked = p.tracked === true && p.available === 0;
  const needsSupplierReview = !p.sourceVerified || !p.supplierLinked;
  let status = 'OK';
  if (zeroTracked) status = 'PURCHASE_BLOCK_RISK';
  if (needsSupplierReview) status = status === 'OK' ? 'SUPPLIER_MAPPING_REVIEW' : status + '+SUPPLIER_MAPPING_REVIEW';
  return { json: { ...p, atlasStatus: status, action: 'ALERT_ONLY_NO_INVENTORY_WRITES', dryRun: true } };
});
